'use client';
import Image from 'next/image';
import {useEffect,useState,useCallback,useMemo, type ReactNode} from 'react';
import {LayoutDashboard,Users,Armchair,Ticket,Settings,LogOut,Plus,ArrowUpRight,ArrowRight,Download,Search,Check,ChevronRight,Copy,Link2,MoreHorizontal,Activity,Clock,MapPin,CalendarDays,Euro,CheckCheck,RefreshCw,LockKeyhole,Eye,EyeOff,Music2,ShieldCheck,Trash2,Pencil,X,Printer,UserPlus,SlidersHorizontal,History,AlertCircle,KeyRound,ExternalLink,Wallet,Menu,LoaderCircle} from 'lucide-react';
import {Sidebar,SidebarProvider,SidebarHeader,SidebarContent,SidebarFooter,SidebarMenu,SidebarMenuItem,SidebarMenuButton,SidebarTrigger,useSidebar} from '@/components/ui/sidebar';
import {Dialog,DialogContent,DialogTitle,DialogDescription,DialogHeader} from '@/components/ui/dialog';
import {AlertDialog,AlertDialogContent,AlertDialogHeader,AlertDialogTitle,AlertDialogDescription,AlertDialogFooter,AlertDialogCancel,AlertDialogAction} from '@/components/ui/alert-dialog';
import {Select,SelectTrigger,SelectValue,SelectContent,SelectItem} from '@/components/ui/select';
