 {modal.type==='list'&&<><Field label="Nome"><input name="name" defaultValue={modal.name} required maxLength={80}/></Field><div className="form-grid"><Field label="Posti massimi"><input name="capacity" type="number" min={Math.max(1,modal.count||0)} max="20000" defaultValue={modal.capacity} readOnly={!admin&&modal.kind==='pista'} required/></Field>{admin&&<Field label="Prezzo a persona (€)" hint="Vuoto = tariffa evento"><input name="price" type="number" min="0" step="0.01" defaultValue={modal.price===null?'':modal.price/100} placeholder={String((modal.kind==='pista'?event.list_price:event.table_price)/100)}/></Field>}</div><Field label="Note interne"><textarea name="note" rows={2} maxLength={500} defaultValue={modal.note}/></Field><div className="switch-row"><div><strong>Accetta nuovi ospiti dal link</strong><small>Puoi chiudere questa lista separatamente.</small></div><Switch checked={!!modal.open} onCheckedChange={v=>setModal({...modal,open:v?1:0})}/></div><div className="list-settings-actions"><Button small secondary onClick={()=>open('invite',{list:modal})}><Link2 size={16}/> Link invito</Button>{modal.kind==='tavolo'&&<button type="button" className="text-btn danger" onClick={()=>setConfirm({title:'Eliminare questo tavolo?',description:`Il tavolo ${modal.name} e i suoi ${modal.count} ospiti verranno rimossi.`,action:async()=>{await mutate('lists/'+modal.id,'DELETE',{},'Tavolo eliminato');setModal(null);}})}><Trash2 size={16}/> Elimina tavolo</button>}</div></>}
 {modal.type==='user'&&<><Field label="Nome del profilo"><input name="name" defaultValue={modal.name} required maxLength={80}/></Field><Field label="Username"><input name="username" defaultValue={modal.username} readOnly={!!modal.id} required pattern="[a-zA-Z0-9._-]+" maxLength={40} placeholder="es. sofia" autoComplete="off"/></Field><Field label={modal.id?'Nuova password (facoltativa)':'Password'} hint="Almeno 6 caratteri. Condividila direttamente con il PR."><input name="password" type="text" required={!modal.id} minLength={6} maxLength={128} autoComplete="new-password" placeholder={modal.id?'Lascia vuoto per mantenere quella attuale':'Scegli una password'}/></Field>{!modal.id&&<Field label="Ruolo"><Pick value={modal.role||'pr'} onChange={(v:string)=>setModal({...modal,role:v})} options={[{value:'pr',label:'PR · solo le proprie liste'},{value:'admin',label:'Organizzatore · accesso completo'}]}/></Field>}{modal.id&&modal.id!==d.user.id&&<div className="switch-row"><div><strong>Profilo attivo</strong><small>Disattivandolo, blocchi accesso e nuovi inviti.</small></div><Switch checked={modal.active!==0} onCheckedChange={v=>setModal({...modal,active:v?1:0})}/></div>}</>}
