 {modal?.type==='invite'&&<div className="invite-modal"><div className="invite-info"><span className="invite-icon">{modal.list.kind==='pista'?<Music2/>:<Armchair/>}</span><div><h3>{modal.list.name}</h3><p>{modal.list.owner_name} · {modal.list.kind==='pista'?'Ingresso pista':'Tavolo'}</p></div></div><div className="url-box">{typeof location!=='undefined'?location.origin:''}/invito/{modal.list.token}</div><Button onClick={()=>copyLink(modal.list)}><Copy size={18}/> Copia link invito</Button><div className="share-buttons"><a className="btn btn-secondary" href={'https://wa.me/?text='+encodeURIComponent(`Sei dei nostri? Iscriviti a ${modal.list.name} per ${event.title}: ${typeof location!=='undefined'?location.origin:''}/invito/${modal.list.token}`)} target="_blank" rel="noreferrer"><Link2 size={17}/> WhatsApp</a><a className="btn btn-secondary" href={'/invito/'+modal.list.token} target="_blank" rel="noreferrer">Apri pagina <ExternalLink size={17}/></a></div>{(!active||!modal.list.open)&&<div className="notice warning"><LockKeyhole size={18}/>Le iscrizioni sono chiuse. Il link tornerà utilizzabile quando verranno riaperte.</div>}<button className="text-btn muted" onClick={()=>setConfirm({title:'Rigenerare il link?',description:'Il vecchio invito smetterà di funzionare. Gli ospiti già iscritti resteranno in lista.',action:async()=>{await mutate('lists/'+modal.list.id,'PATCH',{rotate:true},'Nuovo link generato');const n=await refresh();setModal({type:'invite',list:n.lists.find((l:any)=>l.id===modal.list.id)});}})}><RefreshCw size={14}/> Rigenera link</button></div>}
